CREATE TABLE m3u_entries (id VARCHAR(36) PRIMARY KEY, source_id VARCHAR(36) NOT NULL, external_key VARCHAR(128) NOT NULL, entry_hash VARCHAR(128) NOT NULL, raw_name VARCHAR(512) NOT NULL, clean_title VARCHAR(512) NOT NULL, year INT, media_type VARCHAR(16) NOT NULL, category VARCHAR(191), subcategory VARCHAR(191), season_number INT, episode_number INT, tvg_logo TEXT, stream_ref TEXT NOT NULL, stream_sealed BOOLEAN NOT NULL DEFAULT FALSE, is_selected BOOLEAN NOT NULL DEFAULT FALSE, sync_status VARCHAR(16) NOT NULL DEFAULT 'NEW', media_file_id VARCHAR(36), last_seen_at VARCHAR(40) NOT NULL, missing_since VARCHAR(40), created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, UNIQUE KEY uq_m3u_entries_key(source_id, external_key), INDEX idx_m3u_entries_group(source_id, category, subcategory), INDEX idx_m3u_entries_type(source_id, media_type), FOREIGN KEY(source_id) REFERENCES remote_sources(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE m3u_source_selections (id VARCHAR(36) PRIMARY KEY, source_id VARCHAR(36) NOT NULL, media_type VARCHAR(16) NOT NULL, category VARCHAR(191), subcategory VARCHAR(191), include_all BOOLEAN NOT NULL DEFAULT FALSE, is_enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, INDEX idx_m3u_selections_source(source_id), FOREIGN KEY(source_id) REFERENCES remote_sources(id) ON DELETE CASCADE) ENGINE=InnoDB;
